const queueExpiredHubProfilePictureUploads = `-- name: QueueExpiredHubProfilePictureUploads :one
WITH expired AS (
    UPDATE vetchium.hub_profile_picture_objects
    SET state = 'pending_delete', upload_expires_at = NULL,
        delete_requested_at = now(),
        next_attempt_at = now() + interval '1 minute'
    WHERE state = 'uploading' AND upload_expires_at <= now()
    RETURNING object_id, hub_user_did
), audit AS (
    INSERT INTO vetchium.audit_events (
        tenant_id, action, entity_type, entity_id, actor_type, actor_id,
        source, payload
    )
    SELECT $1, 'hub.profile.picture-upload-expired',
        'hub_profile_picture', object_id::text, 'worker', NULL,
        'workers', jsonb_build_object('hub_user_did', hub_user_did)
    FROM expired
)
SELECT count(*)::integer AS expired_count FROM expired
`

func (q *Queries) QueueExpiredHubProfilePictureUploads(ctx context.Context, tenantID string) (int32, error) {
	row := q.db.QueryRow(ctx, queueExpiredHubProfilePictureUploads, tenantID)
	var expired_count int32
	err := row.Scan(&expired_count)
	return expired_count, err
}

const removeHubProfilePicture = `-- name: RemoveHubProfilePicture :one
WITH owner AS (
    SELECT u.hub_user_did
    FROM vetchium.hub_users AS u
    WHERE u.hub_user_did = $1
      AND u.hub_user_state = 'active'
    FOR UPDATE
), removed AS (
    UPDATE vetchium.hub_profile_picture_objects AS p
    SET state = 'pending_delete', delete_requested_at = now(),
        next_attempt_at = now() + interval '1 minute'
    FROM owner
    WHERE p.hub_user_did = owner.hub_user_did AND p.state = 'active'
    RETURNING p.object_id, p.hub_user_did
), versioned AS (
    UPDATE vetchium.hub_users AS u
    SET profile_version = profile_version + 1, updated_at = now()
    WHERE u.hub_user_did = (SELECT hub_user_did FROM removed)
    RETURNING profile_version
), audit AS (
    INSERT INTO vetchium.audit_events (
        tenant_id, action, entity_type, entity_id, actor_type, actor_id,
        source, idempotency_key, payload
    )
    SELECT $2, 'hub.profile.picture-removed',
        'hub_profile_picture', object_id::text, 'hub_user',
        hub_user_did::text, 'hub-api', $3,
        jsonb_build_object('profile_version', versioned.profile_version)
    FROM removed CROSS JOIN versioned
)
SELECT removed.object_id, versioned.profile_version
FROM removed CROSS JOIN versioned
`

type RemoveHubProfilePictureParams struct {
	HubUserDid     pgtype.UUID `json:"hub_user_did"`
	TenantID       string      `json:"tenant_id"`
	IdempotencyKey pgtype.Text `json:"idempotency_key"`
}

type RemoveHubProfilePictureRow struct {
	ObjectID       pgtype.UUID `json:"object_id"`
	ProfileVersion int64       `json:"profile_version"`
}

func (q *Queries) RemoveHubProfilePicture(ctx context.Context, arg RemoveHubProfilePictureParams) (RemoveHubProfilePictureRow, error) {
	row := q.db.QueryRow(ctx, removeHubProfilePicture, arg.HubUserDid, arg.TenantID, arg.IdempotencyKey)
	var i RemoveHubProfilePictureRow
	err := row.Scan(&i.ObjectID, &i.ProfileVersion)
	return i, err
}

const retireHubProfilePictureForReplacement = `-- name: RetireHubProfilePictureForReplacement :many
WITH owner AS (
    SELECT u.hub_user_did
    FROM vetchium.hub_users AS u
    WHERE u.hub_user_did = $1
      AND u.hub_user_state = 'active'
      AND u.hub_plan_oid = ANY($2::text[])
    FOR UPDATE
), candidate AS (
    SELECT p.object_id, p.hub_user_did
    FROM vetchium.hub_profile_picture_objects AS p
    JOIN owner USING (hub_user_did)
    WHERE p.object_id = $3
      AND p.state = 'uploading'
      AND p.upload_expires_at > now()
)
UPDATE vetchium.hub_profile_picture_objects AS old
SET state = 'pending_delete', delete_requested_at = now(),
    upload_expires_at = NULL, next_attempt_at = now() + interval '1 minute'
WHERE old.hub_user_did = (SELECT hub_user_did FROM candidate)
  AND old.state = 'active'
RETURNING old.object_id
`

type RetireHubProfilePictureForReplacementParams struct {
	HubUserDid       pgtype.UUID `json:"hub_user_did"`
	EntitledPlanOids []string    `json:"entitled_plan_oids"`
	ObjectID         pgtype.UUID `json:"object_id"`
}

// Call before ActivateHubProfilePicture in the same transaction. PostgreSQL
// does not order sibling data-modifying CTEs, so a single statement cannot
// reliably vacate the active-user unique index before activating the new row.
func (q *Queries) RetireHubProfilePictureForReplacement(ctx context.Context, arg RetireHubProfilePictureForReplacementParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, retireHubProfilePictureForReplacement, arg.HubUserDid, arg.EntitledPlanOids, arg.ObjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var object_id pgtype.UUID
		if err := rows.Scan(&object_id); err != nil {
			return nil, err
		}
		items = append(items, object_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const retryHubProfilePictureDeletion = `-- name: RetryHubProfilePictureDeletion :execrows
UPDATE vetchium.hub_profile_picture_objects
SET lease_token = NULL, leased_until = NULL,
    next_attempt_at = now() + LEAST(
        interval '5 minutes',
        interval '1 second' * power(2, LEAST(attempt_count, 8))
    ),
    last_error = left($1, 200)
WHERE object_id = $2
  AND state = 'pending_delete'
  AND lease_token = $3
`

type RetryHubProfilePictureDeletionParams struct {
	LastError  string      `json:"last_error"`
	ObjectID   pgtype.UUID `json:"object_id"`
	LeaseToken pgtype.UUID `json:"lease_token"`
}

func (q *Queries) RetryHubProfilePictureDeletion(ctx context.Context, arg RetryHubProfilePictureDeletionParams) (int64, error) {
	result, err := q.db.Exec(ctx, retryHubProfilePictureDeletion, arg.LastError, arg.ObjectID, arg.LeaseToken)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const supersedeHubProfessionalEmailChallenges = `-- name: SupersedeHubProfessionalEmailChallenges :execrows
UPDATE vetchium.hub_professional_email_challenges AS old
SET superseded_at = now()
WHERE old.professional_email_id = $1
  AND EXISTS (
      SELECT 1 FROM vetchium.hub_professional_emails AS e
      JOIN vetchium.hub_users AS u USING (hub_user_did)
      WHERE e.professional_email_id = old.professional_email_id
        AND e.hub_user_did = $2
        AND u.hub_user_state = 'active'
      FOR UPDATE OF e, u
  )
  AND old.consumed_at IS NULL
  AND old.superseded_at IS NULL
  AND old.attempt_count < 5
`

type SupersedeHubProfessionalEmailChallengesParams struct {
	ProfessionalEmailID pgtype.UUID `json:"professional_email_id"`
	HubUserDid          pgtype.UUID `json:"hub_user_did"`
}

// Call before IssueHubProfessionalEmailChallenge in the same transaction.
// Sibling data-modifying CTEs cannot reliably vacate the active-email index.
func (q *Queries) SupersedeHubProfessionalEmailChallenges(ctx context.Context, arg SupersedeHubProfessionalEmailChallengesParams) (int64, error) {
	result, err := q.db.Exec(ctx, supersedeHubProfessionalEmailChallenges, arg.ProfessionalEmailID, arg.HubUserDid)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const supersedeHubProfilePictureUploads = `-- name: SupersedeHubProfilePictureUploads :one
WITH owner AS (
    SELECT u.hub_user_did
    FROM vetchium.hub_users AS u
    WHERE u.hub_user_did = $1
      AND u.hub_user_state = 'active'
      AND u.hub_plan_oid = ANY($2::text[])
    FOR UPDATE
), retired AS (
    UPDATE vetchium.hub_profile_picture_objects AS p
    SET state = 'pending_delete', upload_expires_at = NULL,
        delete_requested_at = now(),
        next_attempt_at = now() + interval '1 minute'
    FROM owner
    WHERE p.hub_user_did = owner.hub_user_did
      AND p.state = 'uploading'
      AND p.object_id <> $3
    RETURNING p.object_id, p.hub_user_did
), audit AS (
    INSERT INTO vetchium.audit_events (
        tenant_id, action, entity_type, entity_id, actor_type, actor_id,
        source, idempotency_key, payload
    )
    SELECT $4, 'hub.profile.picture-upload-superseded',
        'hub_profile_picture', object_id::text, 'hub_user',
        hub_user_did::text, 'hub-api', $5,
        '{}'::jsonb
    FROM retired
)
SELECT count(*)::integer AS retired_count FROM retired
`

type SupersedeHubProfilePictureUploadsParams struct {
	HubUserDid       pgtype.UUID `json:"hub_user_did"`
	EntitledPlanOids []string    `json:"entitled_plan_oids"`
	ObjectID         pgtype.UUID `json:"object_id"`
	TenantID         string      `json:"tenant_id"`
	IdempotencyKey   pgtype.Text `json:"idempotency_key"`
}

// An in-flight PutObject is bounded to 30 seconds; delay deletion for one
// minute so a superseded upload cannot recreate bytes after the worker deletes.
func (q *Queries) SupersedeHubProfilePictureUploads(ctx context.Context, arg SupersedeHubProfilePictureUploadsParams) (int32, error) {
	row := q.db.QueryRow(ctx, supersedeHubProfilePictureUploads,
		arg.HubUserDid,
		arg.EntitledPlanOids,
		arg.ObjectID,
		arg.TenantID,
		arg.IdempotencyKey,
	)
	var retired_count int32
	err := row.Scan(&retired_count)
	return retired_count, err
}

const verifyHubProfessionalEmailChallenge = `-- name: VerifyHubProfessionalEmailChallenge :one
WITH candidate AS (
    SELECT c.challenge_id, c.professional_email_id, c.code_hash,
        c.attempt_count, e.hub_user_did
    FROM vetchium.hub_professional_email_challenges AS c
    JOIN vetchium.hub_professional_emails AS e USING (professional_email_id)
    JOIN vetchium.hub_users AS u USING (hub_user_did)
    WHERE c.challenge_id = $1
      AND e.professional_email_id = $2
      AND e.hub_user_did = $3
      AND u.hub_user_state = 'active'
      AND c.consumed_at IS NULL
      AND c.superseded_at IS NULL
      AND c.expires_at > now()
      AND c.attempt_count < 5
    FOR UPDATE OF c, e
), attempted AS (
    UPDATE vetchium.hub_professional_email_challenges AS c
    SET attempt_count = c.attempt_count + 1,
        consumed_at = CASE
            WHEN c.code_hash = $4 THEN now()
            ELSE NULL
        END
    FROM candidate
    WHERE c.challenge_id = candidate.challenge_id
    RETURNING c.challenge_id, c.professional_email_id, c.attempt_count,
        candidate.hub_user_did,
        candidate.code_hash = $4 AS verified
), verified_email AS (
    UPDATE vetchium.hub_professional_emails AS e
    SET first_verified_at = COALESCE(e.first_verified_at, now()),
        last_verified_at = now(),
        updated_at = now()
    FROM attempted
    WHERE e.professional_email_id = attempted.professional_email_id
      AND attempted.verified
    RETURNING e.professional_email_id, e.first_verified_at,
        e.last_verified_at
), audit AS (
    INSERT INTO vetchium.audit_events (
        tenant_id, action, entity_type, entity_id, actor_type, actor_id,
        source, idempotency_key, payload
    )
    SELECT $5,
        CASE WHEN attempted.verified
            THEN 'hub.profile.professional-email-verified'
            ELSE 'hub.profile.professional-email-verification-failed' END,
        'hub_professional_email', attempted.professional_email_id::text,
        'hub_user', attempted.hub_user_did::text, 'hub-api',
        $6,
        jsonb_build_object('attempt_count', attempted.attempt_count)
    FROM attempted
)
SELECT attempted.challenge_id, attempted.attempt_count, attempted.verified,
    verified_email.first_verified_at, verified_email.last_verified_at
FROM attempted
LEFT JOIN verified_email USING (professional_email_id)
`

type VerifyHubProfessionalEmailChallengeParams struct {
	ChallengeID         pgtype.UUID `json:"challenge_id"`
	ProfessionalEmailID pgtype.UUID `json:"professional_email_id"`
	HubUserDid          pgtype.UUID `json:"hub_user_did"`
	CodeHash            []byte      `json:"code_hash"`
	TenantID            string      `json:"tenant_id"`
	IdempotencyKey      pgtype.Text `json:"idempotency_key"`
}

type VerifyHubProfessionalEmailChallengeRow struct {
	ChallengeID     pgtype.UUID        `json:"challenge_id"`
	AttemptCount    int32              `json:"attempt_count"`
	Verified        bool               `json:"verified"`
	FirstVerifiedAt pgtype.Timestamptz `json:"first_verified_at"`
	LastVerifiedAt  pgtype.Timestamptz `json:"last_verified_at"`
}

func (q *Queries) VerifyHubProfessionalEmailChallenge(ctx context.Context, arg VerifyHubProfessionalEmailChallengeParams) (VerifyHubProfessionalEmailChallengeRow, error) {
	row := q.db.QueryRow(ctx, verifyHubProfessionalEmailChallenge,
		arg.ChallengeID,
		arg.ProfessionalEmailID,
		arg.HubUserDid,
		arg.CodeHash,
		arg.TenantID,
		arg.IdempotencyKey,
	)
	var i VerifyHubProfessionalEmailChallengeRow
	err := row.Scan(
		&i.ChallengeID,
		&i.AttemptCount,
		&i.Verified,
		&i.FirstVerifiedAt,
		&i.LastVerifiedAt,
	)
	return i, err
}
